// Görüş sahnesinin saf mantığı: sarmalayan gezinme, baş harfler ve yazımlar. Sayılar ABACUS'tandır.
import { text } from "@snn/abacus-core";

/** Sekmeler arasında bir adım: listenin sonunda başa, başında sona sarar. */
export function wrapIndex(index: number, step: number, count: number): number {
  if (count <= 0) return 0;
  return (((index + step) % count) + count) % count;
}

/** Portre yer tutucusu için baş harfler (en çok iki): "Elif Aksoy" → "EA"; Türkçe büyük harf kurallıdır. */
export function initials(name: string): string {
  return name.trim().split(/\s+/).slice(0, 2).map(part => text.upper(part[0] ?? "")).join("");
}

export const tabLabel = (name: string, role: string): string => `${name}, ${role}`;
export const liveText = (name: string): string => `${name} görüşü gösteriliyor.`;
export const portraitLabel = (name: string, role: string): string => `${name}, ${role} portresi`;
/** Geçiş yönü: sonraki kişi sağdan, önceki soldan gelir (sarmada da seçilen kişinin sırasına bakar). */
export const directionOf = (from: number, to: number): 1 | -1 => to >= from ? 1 : -1;

.root { container-type: inline-size; display: grid; gap: var(--space-5); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); min-width: 0; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.tabs { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.tab { transition: background var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard), transform var(--duration-fast) var(--ease-standard); position: relative; display: inline-flex; align-items: center; gap: var(--space-2); padding: var(--space-2) var(--space-3); border: 0; border-radius: var(--radius-control); background: none; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); cursor: pointer; }
.tab[aria-selected="true"] { color: var(--foreground); }
.tab:hover { background: var(--surface-muted); color: var(--foreground); }
.tab:active { transform: scale(.97); }
.tab:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.tab[aria-selected="true"] .mini { background: var(--accent); color: var(--accent-foreground); }
.mini { transition: background var(--duration-fast) var(--ease-standard); display: grid; place-items: center; width: 1.75rem; height: 1.75rem; border-radius: 50%; background: var(--accent-subtle); color: var(--accent-strong); font-size: var(--text-xs); }
.underline { position: absolute; left: var(--space-3); right: var(--space-3); bottom: 0; height: 2px; border-radius: 1px; background: var(--foreground); }
.stage { min-height: 20rem; }
.slide { display: grid; grid-template-columns: minmax(0, 16rem) minmax(0, 1fr); gap: var(--space-8); align-items: center; }
.portrait { display: block; width: 100%; border-radius: var(--radius-panel); box-shadow: var(--shadow-raised); }
.initials { font-family: var(--font-display); font-size: var(--text-5xl); }
.quote { margin: 0; display: grid; gap: var(--space-4); }
.quote { position: relative; padding-top: var(--space-10); }
.quote::before { content: "“"; position: absolute; top: 0; left: -.02em; color: var(--accent); font-family: var(--font-display); font-size: var(--text-5xl); line-height: .8; opacity: .45; }
.quote blockquote { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); line-height: 1.2; letter-spacing: var(--tracking-display); text-wrap: pretty; }
.quote figcaption { display: grid; gap: 2px; padding-top: var(--space-3); border-top: 1px solid var(--border-subtle); font-size: var(--text-sm); }
.quote figcaption b { font-family: var(--font-display); font-size: var(--text-base); font-weight: 500; }
.quote figcaption span { color: var(--text-secondary); }
.skeleton { display: grid; gap: var(--space-3); }
.skeleton span { display: block; height: 2rem; border-radius: var(--radius-control); background: var(--neutral-3); animation: pulse 1.4s ease-in-out infinite; }
.skeleton span:first-child { height: 8rem; }
@keyframes pulse { 50% { opacity: .5; } }
.root[data-reduced] .skeleton span { animation: none; }
.root[data-reduced] .tab, .root[data-reduced] .mini { transition: none; }
@media (prefers-reduced-motion: reduce) { .skeleton span { animation: none; } }
@container (max-width: 800px) { .slide { gap: var(--space-5); } .quote blockquote { font-size: var(--text-2xl); } }
@container (max-width: 680px) { .slide { grid-template-columns: minmax(0, 1fr); justify-items: start; } .portrait { max-width: 11rem; } }
@container (max-width: 350px) { .root { padding: var(--space-4); } .quote blockquote { font-size: var(--text-xl); } .tabName { display: none; } }

"use client";

import { useId, useRef, useState, type KeyboardEvent } from "react";
import { AnimatePresence, motion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import { Photo, useAnnouncer } from "../lib/shop-parts";
import { useElementWidth, useReducedMotionSafe } from "../lib/viz-utils";
import { directionOf, initials, liveText, portraitLabel, tabLabel, wrapIndex } from "./testimonial-stage-format";
import styles from "./testimonial-stage.module.css";

export interface Testimonial {
  id: string;
  name: string;
  role: string;
  company: string;
  quote: string;
  /** Verilirse gerçek portre; verilmezse baş harfli yer tutucu çizilir. */
  portrait?: string;
  /** Portrenin odak noktası (CSS object-position), örneğin "50% 30%". */
  portraitPosition?: string;
  /** Yer tutucunun renk tonu (0–5). */
  tone?: number;
}

/** Birkaç kişinin görüşünü, kişinin portresi öne çıkacak biçimde göstermek için kullanın: üstte kişi sekmeleri, altta seçili kişinin portresi ve alıntısı. Kendiliğinden dönmez, yalnız kullanıcı girdisiyle değişir. Yalnız logo yeterliyse logo şeridi, çok sayıda kısa yorum için döner şerit, kendi ekibi için `team-showcase`. Gerçek sitede yalnız izin alınmış portre ve doğrulanmış alıntı kullanılmalıdır (uygulamanın sorumluluğu). */
export interface TestimonialStageProps {
  title: string;
  people: Testimonial[];
  /** Seçim değişince çağrılır (istatistik için). */
  onSelect?: (person: Testimonial, index: number) => void;
  loading?: boolean;
}

function Portrait({ person }: { person: Testimonial }) {
  return <Photo src={person.portrait} position={person.portraitPosition ?? "50% 25%"} alt={portraitLabel(person.name, person.role)} ratio="4 / 5" tone={person.tone} initial={initials(person.name)} className={styles.portrait} />;
}

export function TestimonialStage({ title, people, onSelect, loading = false }: TestimonialStageProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const [box, width] = useElementWidth<HTMLElement>();
  const [index, setIndex] = useState(0);
  const direction = useRef(1);
  const tabs = useRef<(HTMLButtonElement | null)[]>([]);
  const [live, announce] = useAnnouncer();
  const person = people[Math.min(index, people.length - 1)];

  const choose = (next: number, focus = false) => {
    if (next === index) return;
    direction.current = directionOf(index, next);
    setIndex(next);
    onSelect?.(people[next]!, next);
    announce(liveText(people[next]!.name));
    if (focus) tabs.current[next]?.focus();
  };
  const key = (event: KeyboardEvent, at: number) => {
    const next = event.key === "ArrowRight" ? wrapIndex(at, 1, people.length) : event.key === "ArrowLeft" ? wrapIndex(at, -1, people.length) : event.key === "Home" ? 0 : event.key === "End" ? people.length - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    choose(next, true);
  };

  if (loading || !person) return <section ref={box} className={styles.root} aria-busy="true" role="status" aria-label="Görüşler yükleniyor"><div className={styles.skeleton}><span /><span /><span /></div></section>;

  const slide = (sign: number) => reduced ? { opacity: 0 } : { opacity: 0, x: 24 * sign };
  return <section ref={box} className={styles.root} aria-labelledby={`${uid}-title`} data-narrow={width > 0 && width < 680 || undefined} data-compact={width > 0 && width < 350 || undefined} data-reduced={reduced || undefined}>
    <h2 id={`${uid}-title`} className={styles.title}>{title}</h2>
    {people.length > 1 && <div className={styles.tabs} role="tablist" aria-label="Kişiler">{people.map((item, at) => <button key={item.id} ref={node => { tabs.current[at] = node; }} type="button" role="tab" id={`${uid}-tab-${item.id}`} aria-selected={at === index} aria-controls={`${uid}-panel`} tabIndex={at === index ? 0 : -1} aria-label={tabLabel(item.name, item.role)} className={styles.tab} onClick={() => choose(at)} onKeyDown={event => key(event, at)}>
      <span className={styles.mini} aria-hidden="true">{initials(item.name)}</span><span className={styles.tabName}>{item.name}</span>
      {at === index && <motion.i layoutId={`${uid}-underline`} className={styles.underline} transition={reduced ? { duration: 0 } : motionTokens.spring.snappy} />}
    </button>)}</div>}
    <div id={`${uid}-panel`} role="tabpanel" aria-labelledby={`${uid}-tab-${person.id}`} className={styles.stage}>
      <AnimatePresence mode="wait" initial={false} custom={direction.current}>
        <motion.div key={person.id} className={styles.slide} initial={slide(direction.current)} animate={{ opacity: 1, x: 0 }} exit={slide(-direction.current)} transition={{ duration: reduced ? 0 : motionTokens.duration.standard, ease: [...motionTokens.ease.standard] }}>
          <Portrait person={person} />
          <figure className={styles.quote}>
            <blockquote>{person.quote}</blockquote>
            <figcaption><b>{person.name}</b><span>{person.role}, {person.company}</span></figcaption>
          </figure>
        </motion.div>
      </AnimatePresence>
    </div>
    {live}
  </section>;
}

export default TestimonialStage;
